import {DEMO_SUPPLIERS,SNAPSHOT,CSV_FIELDS,riskScore,riskLevel,riskFactors,estimatedDelay,simulate,makeShipments,summarize,importSuppliers,toCSV} from './model.js';
import {icon} from './icons.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v,compact=true)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:compact?1:0,notation:compact?'compact':'standard'}).format(v);
const pct=n=>`${Number(n).toFixed(1)}%`;
const levelName=l=>({high:'High risk',medium:'Medium risk',low:'Low risk'}[l]);
const badge=(score)=>{const l=riskLevel(score);return `<span class="badge ${l}"><i class="dot ${l}"></i>${levelName(l)}</span>`;};
const pages={overview:'Overview',suppliers:'Suppliers',shipments:'Shipments',scenarios:'Scenario lab',actions:'Action plan'};
let saved={};try{saved=JSON.parse(localStorage.getItem('supplychainrisk-v1')||'{}');if(!saved||typeof saved!=='object')saved={};}catch{}
let imported=[];try{if(Array.isArray(saved.imported)&&saved.imported.length) imported=importSuppliers(toCSV(saved.imported,CSV_FIELDS),DEMO_SUPPLIERS.map(s=>s.id));}catch{}
const defaultTasks=[{id:'task-demo-1',supplierId:'SUP-001',title:'Review alternate sources for Shenzhen Precision',note:'Demo task · Compare qualified electronics suppliers to reduce category dependency.',done:false,source:'Demo task'},{id:'task-demo-2',supplierId:'SUP-002',title:'Confirm the next delivery window with Mekong Components',note:'Demo task · Review historical delays and add an appropriate planning buffer.',done:false,source:'Demo task'}];
const state={page:pages[location.hash.slice(1)]?location.hash.slice(1):'overview',risk:'all',region:'all',query:'',sort:'score',sortDir:-1,shipmentFilter:'All',shipmentQuery:'',shipmentMode:'all',scenarioId:'SUP-001',params:{reliability:0,disruption:0,buffer:0,diversification:0},watchlist:Array.isArray(saved.watchlist)?saved.watchlist.filter(x=>typeof x==='string'):['SUP-001','SUP-004'],tasks:Array.isArray(saved.tasks)?saved.tasks.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string').map(x=>({...x,done:!!x.done})):defaultTasks.map(t=>({...t})),scenarios:Array.isArray(saved.scenarios)?saved.scenarios.filter(x=>x&&typeof x.supplierName==='string'&&Number.isFinite(x.before)&&Number.isFinite(x.after)):[],imported};
const suppliers=()=>[...DEMO_SUPPLIERS,...state.imported];
const findSupplier=id=>suppliers().find(s=>s.id===id);
const sortedSuppliers=()=>suppliers().sort((a,b)=>riskScore(b)-riskScore(a));
const shipments=()=>makeShipments(DEMO_SUPPLIERS);
let overlayReturnFocus=null,activeSupplier=null,toastTimeout,storageWarning=false;
function persist(){try{localStorage.setItem('supplychainrisk-v1',JSON.stringify({watchlist:state.watchlist,tasks:state.tasks,scenarios:state.scenarios,imported:state.imported}));}catch{if(!storageWarning){storageWarning=true;toast('Browser storage is unavailable. Changes will last for this session.');}}}
function toast(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function download(content,filename,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function nav(page){if(!pages[page])return;state.page=page;location.hash=page;closeOverlay(false);render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function navLink(page,name){return `<a class="nav-link ${state.page===page?'active':''}" href="#${page}" data-nav="${page}" ${state.page===page?'aria-current="page"':''}>${icon(name)}<span>${pages[page]}</span>${page==='actions'?`<span class="nav-count">${state.tasks.filter(t=>!t.done).length}</span>`:''}</a>`;}
function render(){
  document.title=`${pages[state.page]} · SupplyChainRisk`;
  $('#app').innerHTML=`<div class="mobile-scrim" data-action="menu-close"></div><aside class="sidebar" aria-label="Main navigation">
    <a href="#overview" data-nav="overview" class="brand"><svg class="brand-mark" viewBox="0 0 34 38" fill="none" aria-hidden="true"><path d="m17 2 14 8v17l-14 9L3 27V10z" stroke="currentColor" stroke-width="1.7"/><path d="m3 10 14 8 14-8M17 18v18M10 6l14 8v9l-7 4" stroke="currentColor" stroke-width="1.7"/></svg><div>SupplyChain<span>Risk</span></div></a><div class="brand-sub">Supplier intelligence</div>
    <div class="nav-label">Workspace</div><nav>${navLink('overview','grid')}${navLink('suppliers','suppliers')}${navLink('shipments','truck')}${navLink('scenarios','sliders')}${navLink('actions','checkList')}</nav>
    <div class="sidebar-bottom"><div class="side-callout"><div class="label">${icon('leaf')}A clearer path forward</div>Understand the signals.<br>Plan your next move.<button data-action="model">How risk is calculated ${icon('arrow')}</button></div><div class="workspace"><div class="avatar">TK</div><div><strong>Tae-In’s workspace</strong><small>Personal project · Prototype</small></div>${icon('down')}</div></div></aside>
    <div class="shell"><header class="topbar"><div class="flex gap-12"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumbs"><span>Workspace</span>${icon('chevron')}<strong>${pages[state.page]}</strong></div></div><div class="top-actions"><button class="search-global" data-action="search" aria-label="Search suppliers and shipments">${icon('search')}<span>Search anything...</span><kbd>⌘ K</kbd></button><span class="header-date">${icon('calendar')}Oct 20, 2026</span><div class="top-divider"></div><button class="icon-button" data-action="signals" aria-label="View priority signals">${icon('bell')}</button><div class="top-avatar" aria-label="Tae-In's demo workspace">TK</div></div></header>
    <main id="main" class="main" tabindex="-1">${({overview:overview,suppliers:supplierPage,shipments:shipmentPage,scenarios:scenarioPage,actions:actionPage}[state.page])()}<footer class="page-footer"><span class="footer-left">${icon('shield')}Demo workspace · Fictional records · Snapshot: Oct 20, 2026</span><button class="footer-link" data-action="model">About the model ${icon('external')}</button></footer></main></div>`;
}
function pageHead(eyebrow,title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;}
const demoLabel='<span class="demo-label"><i class="demo-dot"></i>Demo dataset</span>';
function stat(iconName,title,value,foot,cls='',spark=false){return `<div class="stat"><div class="stat-top"><span>${title}</span><span class="stat-icon ${cls}">${icon(iconName)}</span></div><div class="stat-value mono">${value}</div><div class="stat-foot">${foot}</div>${spark?'<svg class="stat-spark" viewBox="0 0 65 28" aria-hidden="true"><path d="M1 24 10 20 17 23 26 16 35 17 42 9 51 11 64 2" fill="none" stroke="#b3c3a3" stroke-width="1.5"/><path d="M1 24 10 20 17 23 26 16 35 17 42 9 51 11 64 2V28H1Z" fill="#f0f4e9"/></svg>':''}</div>`;}
function overview(){const all=suppliers(),s=summarize(all),countries=new Set(all.map(s=>s.country)).size;return `${pageHead('YOUR NETWORK, IN FOCUS','Supply chain overview','A little foresight. A more resilient supply chain.',`${demoLabel}<button class="btn" data-action="export">${icon('download')}Export report</button>`)}
  <section class="stats" aria-label="Portfolio metrics">${stat('suppliers','Active suppliers',s.total,`<b>${countries} countries</b><span>across your network</span>`,'',true)}${stat('warning','High-risk suppliers',s.high,`<b class="red">${Math.round(s.high/s.total*100)}% of portfolio</b><span>need attention</span>`,'red')}${stat('truck','On-time delivery',`${s.onTime.toFixed(1)}<span class="unit">%</span>`,`<b>Spend-weighted</b><span>historical rate</span>`,'',true)}${stat('dollar','Annual spend at risk',money(s.atRisk),`<b class="red">${Math.round(s.atRisk/s.spend*100)}% of total spend</b>`,'red')}</section>
  <div class="overview-focus"><div class="focus-copy">${icon('spark')}<div><strong>${s.high} suppliers could use a closer look.</strong><span>Start with the highest-impact risks.</span></div></div><button class="text-button" data-action="review-high">Review suppliers ${icon('arrow')}</button></div>
  <section class="grid-main"><div class="card map-card"><div class="card-head"><div><h2>Your global network</h2><p class="card-desc">${all.filter(s=>Number.isFinite(s.lat)).length} mapped suppliers · ${countries} countries · One connected view</p></div><span class="small-tag">Supplier locations</span></div><div class="map-wrap">${worldMap()}<button class="map-tooltip" data-action="supplier" data-id="SUP-001"><span class="tiny-icon">${icon('warning')}</span><span><strong>Shenzhen Precision</strong><small>High risk · ${riskScore(findSupplier('SUP-001'))}/100 risk index</small></span></button></div><div class="map-bottom"><div class="legend"><span><i class="dot low"></i>Low risk</span><span><i class="dot medium"></i>Medium risk</span><span><i class="dot high"></i>High risk</span></div><span>Illustrative routes to US hub</span></div></div>${signalCard()}</section>
  <section><div class="section-header"><div class="section-title-group"><h2>Supplier risk watch</h2><span class="count-pill">${all.length} suppliers</span></div><button class="text-button" data-nav="suppliers">View all suppliers ${icon('arrow')}</button></div>${supplierTable(true)}</section>`;}
function worldMap(){
  // Simplified equirectangular coastlines; routes illustrate connections only.
  const project=(lon,lat)=>[(lon+180)/360*700,(82-lat)/145*265];
  const outlines=[
  [[-168,70],[-150,72],[-140,69],[-130,72],[-116,70],[-106,73],[-91,81],[-73,79],[-63,70],[-56,55],[-65,48],[-75,45],[-82,29],[-87,25],[-90,20],[-87,16],[-82,9],[-78,8],[-79,13],[-85,18],[-95,20],[-104,25],[-114,32],[-123,42],[-128,52],[-140,60],[-153,58],[-165,62]],
  [[-52,59],[-44,61],[-35,70],[-20,76],[-26,82],[-48,82],[-60,76],[-65,67]],
  [[-81,12],[-70,12],[-61,8],[-52,3],[-37,-5],[-35,-10],[-40,-20],[-48,-27],[-53,-34],[-58,-39],[-66,-55],[-73,-53],[-75,-37],[-71,-19],[-78,-5]],
  [[-11,36],[-8,43],[-1,45],[5,43],[8,48],[3,52],[9,55],[6,59],[12,70],[28,71],[35,65],[42,68],[53,68],[60,73],[80,74],[100,78],[119,73],[140,74],[160,69],[179,66],[170,59],[155,56],[146,49],[140,43],[133,42],[129,38],[122,40],[120,33],[122,28],[115,22],[108,20],[109,12],[104,9],[101,14],[99,20],[94,20],[91,22],[85,20],[80,7],[76,9],[73,19],[68,23],[60,26],[56,24],[51,13],[44,13],[42,19],[36,30],[32,31],[27,40],[21,40],[19,45],[15,42],[13,45],[8,43],[5,37],[0,36]],
  [[-17,28],[-9,36],[2,37],[11,34],[23,33],[32,31],[34,23],[42,13],[51,11],[48,4],[43,-1],[40,-11],[35,-20],[30,-29],[20,-35],[16,-28],[12,-18],[11,-4],[8,4],[-1,5],[-7,4],[-13,9],[-17,16]],
  [[112,-11],[122,-14],[130,-12],[136,-11],[142,-10],[145,-18],[153,-24],[151,-32],[143,-39],[132,-33],[120,-35],[114,-31]],
  [[-9,50],[-6,50],[-3,54],[-5,58],[-8,57]], [[129,31],[132,33],[136,34],[140,39],[143,44],[145,44],[142,37],[138,34],[133,31]],
  [[47,-13],[50,-16],[48,-23],[44,-26],[44,-20]], [[95,6],[99,2],[105,-5],[103,-6],[98,-1]], [[106,-6],[114,-7],[121,-9],[115,-9]], [[109,1],[115,6],[119,5],[117,-3],[111,-3]], [[120,18],[123,13],[126,8],[123,5],[121,11]], [[167,-35],[178,-39],[173,-43],[168,-46],[166,-44],[174,-40]]
  ];
  const hub=project(-86.1,39.8),colors={high:'#cc8d73',medium:'#c9ac66',low:'#87a276'};
  return `<svg class="world-map" viewBox="0 0 700 285" role="img" aria-label="Supplier locations across the Americas, Europe and Asia Pacific. Select a location to inspect its supplier."><defs><radialGradient id="mapglow"><stop stop-color="#f8faf4"/><stop offset="1" stop-color="#fff"/></radialGradient></defs><rect width="700" height="285" fill="url(#mapglow)"/>${[60,120,180,240].map(y=>`<path class="map-grid" d="M0 ${y}H700"/>`).join('')}${[100,200,300,400,500,600].map(x=>`<path class="map-grid" d="M${x} 0V265"/>`).join('')}${outlines.map(poly=>`<path class="map-land" d="${poly.map(([lon,lat],i)=>`${i?'L':'M'}${project(lon,lat).map(v=>v.toFixed(1)).join(' ')}`).join('')}Z"/>`).join('')}${suppliers().filter(s=>Number.isFinite(s.lat)).map(s=>{const [x,y]=project(s.lon,s.lat);return `<path class="map-route" d="M${hub[0]} ${hub[1]}Q${(x+hub[0])/2} ${Math.min(y,hub[1])-55} ${x} ${y}"/>`;}).join('')}<text class="map-label" x="96" y="117">AMERICAS</text><text class="map-label" x="344" y="60">EUROPE</text><text class="map-label" x="530" y="70">ASIA PACIFIC</text>${suppliers().filter(s=>Number.isFinite(s.lat)).map(s=>{const [x,y]=project(s.lon,s.lat),l=riskLevel(riskScore(s));return `<g class="map-pin" role="button" tabindex="0" aria-label="Inspect ${esc(s.name)}, ${levelName(l)}" data-action="supplier" data-id="${esc(s.id)}"><title>${esc(s.name)} · ${esc(s.city)}, ${esc(s.country)}</title><circle class="ring" cx="${x}" cy="${y}" r="10" fill="${colors[l]}" opacity=".12"/><circle class="dot" cx="${x}" cy="${y}" r="4.5" fill="${colors[l]}"/></g>`;}).join('')}<circle cx="${hub[0]}" cy="${hub[1]}" r="3" fill="#3c5936"/><text x="${hub[0]-38}" y="${hub[1]+18}" font-size="7" fill="#7b9068">US DISTRIBUTION HUB</text></svg>`;
}
function signalCard(){const risky=sortedSuppliers().filter(s=>riskScore(s)>=35).slice(0,3);return `<aside class="card signals"><div class="card-head"><h2>Priority signals</h2><span class="small-tag">${risky.length} to explore</span></div><p class="signal-summary">Small signals. Meaningful next steps.</p>${risky.map((s,i)=>`<button class="signal-item" data-action="supplier" data-id="${esc(s.id)}"><span class="signal-icon ${i===2?'amber':''}">${icon(i===0?'clock':i===1?'warning':'suppliers')}</span><span class="signal-copy"><strong>${esc(i===0?'Delivery delays building up':i===1?'Reliability below target':'High supplier dependency')}</strong><p>${esc(s.name)} · ${i===0?`${s.avg_delay_days}-day average delay`:i===1?`${s.on_time_rate}% on-time delivery`:`${s.dependency}% category dependency`}</p><span class="signal-meta"><span>${esc(s.country)}</span><span>•</span><span>Demo signal</span></span></span>${icon('chevron')}</button>`).join('')}<div class="signals-footer"><button class="text-button" data-nav="scenarios">Explore a mitigation scenario ${icon('arrow')}</button></div></aside>`;}
function filteredSuppliers(){return suppliers().filter(s=>{const l=riskLevel(riskScore(s));return (state.risk==='all'||state.risk===l||(state.risk==='watchlist'&&state.watchlist.includes(s.id)))&&(state.region==='all'||s.region===state.region)&&`${s.name} ${s.country} ${s.category} ${s.id}`.toLowerCase().includes(state.query.toLowerCase());}).sort((a,b)=>{const av=state.sort==='score'?riskScore(a):a[state.sort],bv=state.sort==='score'?riskScore(b):b[state.sort];return state.sortDir*(typeof av==='string'?av.localeCompare(bv):av-bv);});}
function tableTabs(){const all=suppliers();return `<div class="tabs" role="group" aria-label="Filter suppliers by risk">${[['all','All suppliers'],['high','High risk'],['watchlist','Watchlist']].map(([v,n])=>`<button class="tab ${state.risk===v?'active':''}" data-risk="${v}" aria-pressed="${state.risk===v}">${n}<span class="count">${v==='all'?all.length:v==='watchlist'?all.filter(s=>state.watchlist.includes(s.id)).length:all.filter(s=>riskLevel(riskScore(s))==='high').length}</span></button>`).join('')}${['medium','low'].includes(state.risk)?`<button class="tab active" aria-pressed="true" data-risk="${state.risk}">${levelName(state.risk)}</button>`:''}</div>`;}
function supplierTable(compact=false){const rows=filteredSuppliers(),shown=compact?rows.slice(0,5):rows;return `<div class="card table-card ${compact?'':'full-table'}"><div class="table-toolbar">${tableTabs()}<div class="filter-set">${!compact?`<div class="input-search">${icon('search')}<input id="supplier-query" aria-label="Search suppliers" placeholder="Search suppliers..." value="${esc(state.query)}"></div><select id="risk-select" aria-label="Risk level"><option value="all">All risk levels</option>${['high','medium','low'].map(l=>`<option value="${l}" ${state.risk===l?'selected':''}>${levelName(l)}</option>`).join('')}</select>`:''}<select id="region-select" aria-label="Supplier region"><option value="all">All regions</option>${['Asia Pacific','Europe','Americas','Middle East & Africa'].map(r=>`<option ${state.region===r?'selected':''}>${r}</option>`).join('')}</select></div></div><div class="table-scroll"><table aria-label="Supplier risk scores"><thead><tr><th><button class="sort-button" data-sort="name">Supplier ${icon('sort')}</button></th><th>Region</th><th>Risk level</th><th><button class="sort-button" data-sort="score">Risk index ${icon('sort')}</button></th><th>${compact?'30-day trend':'Estimated delay'}</th>${!compact?'<th>Annual spend</th>':''}<th><span class="small">Watch</span></th></tr></thead><tbody id="supplier-rows">${supplierRows(shown,compact)}</tbody></table></div><div id="supplier-table-foot" class="table-foot">${supplierFoot(rows.length,shown.length,compact)}</div></div>`;}
function supplierRows(rows,compact){if(!rows.length)return `<tr><td colspan="${compact?6:7}"><div class="empty">${icon('search')}<h3>No suppliers found</h3><p>Try another search or clear your filters.</p><button class="btn" data-action="clear-filters">Clear filters</button></div></td></tr>`;return rows.map(s=>{const score=riskScore(s),l=riskLevel(score);return `<tr><td><button class="supplier-cell" data-action="supplier" data-id="${esc(s.id)}"><span class="supplier-logo ${l}">${esc(s.initials)}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.category)}${s.imported?' · Imported':''}</small></span></button></td><td><div class="metric-pair"><strong>${esc(s.country)}</strong><small>${esc(s.region)}</small></div></td><td>${badge(score)}</td><td><div class="score-cell"><b class="${l}">${score}</b><div class="score-track"><div class="score-fill ${l}" style="width:${score}%"></div></div></div></td><td>${compact?`<span class="trend ${s.trend>0?'up':'down'}">${icon(s.trend>0?'arrowUp':'arrowDown')}${s.trend>0?'+':''}${s.trend}<span class="muted">pts</span></span>`:`<span class="mono">${estimatedDelay(s)} days</span>`}</td>${compact?'':`<td class="mono">${money(s.spend)}</td>`}<td><button class="icon-button watch-button ${state.watchlist.includes(s.id)?'on':''}" data-action="watch" data-id="${esc(s.id)}" aria-label="${state.watchlist.includes(s.id)?'Remove':'Add'} ${esc(s.name)} ${state.watchlist.includes(s.id)?'from':'to'} watchlist" aria-pressed="${state.watchlist.includes(s.id)}">${icon('star')}</button></td></tr>`;}).join('');}
function supplierFoot(total,shown,compact){return `<span>Showing ${shown} of ${total} matching suppliers · Scores are demo estimates</span>${compact?`<button class="text-button" data-nav="suppliers">View directory ${icon('arrow')}</button>`:`<button class="text-button" data-action="clear-filters">Reset filters ${icon('reset')}</button>`}`;}
function updateSupplierTable(){const rows=filteredSuppliers(),compact=state.page==='overview',shown=compact?rows.slice(0,5):rows;$('#supplier-rows').innerHTML=supplierRows(shown,compact);$('#supplier-table-foot').innerHTML=supplierFoot(rows.length,shown.length,compact);}
function supplierPage(){const all=suppliers();return `${pageHead('SUPPLIER INTELLIGENCE','Know your suppliers. See the signals.','Explore risk, reliability, and exposure across every relationship.',`<button class="btn" data-action="import">${icon('upload')}Import CSV</button><button class="btn primary" data-action="export">${icon('download')}Export suppliers</button>`)}${state.imported.length?`<div class="info-banner">${icon('info')}<div><strong>${state.imported.length} imported suppliers included.</strong> Imported records are stored in this browser. Location maps and shipment records use the original demo dataset.</div></div>`:''}<section class="split-cards"><div class="card"><div class="card-head"><h2>Portfolio risk distribution</h2><span class="small-tag">${all.length} suppliers</span></div>${distribution(all)}</div><div class="card"><div class="card-head"><h2>The inputs behind the index</h2><button class="text-button" data-action="model">View method ${icon('arrow')}</button></div><div style="padding:3px 24px 22px">${[['Delivery reliability',40],['Historical delays',25],['Quality issues',15],['Supplier dependency',12],['Lead-time volatility',8]].map(([n,w])=>`<div class="factor" style="margin:12px 0"><div class="factor-head"><span>${n}</span><strong>${w}%</strong></div><div class="factor-bar"><i style="width:${w*2}%"></i></div></div>`).join('')}</div></div></section>${supplierTable()}`;}
function distribution(all){const values=['low','medium','high'].map(l=>all.filter(s=>riskLevel(riskScore(s))===l).length),total=all.length;const a=values[0]/total*100,b=a+values[1]/total*100;return `<div class="distribution"><div class="donut" role="img" aria-label="${values[0]} low risk, ${values[1]} medium risk, ${values[2]} high risk" style="background:conic-gradient(#8faa79 0 ${a}%,#d3b879 ${a}% ${b}%,#d79b81 ${b}% 100%)"><div class="donut-center">${total}<small>Total suppliers</small></div></div><div class="distribution-legend">${['low','medium','high'].map((l,i)=>`<button class="distribution-item" style="width:100%;padding:0" data-risk="${l}" aria-label="Show ${levelName(l).toLowerCase()} suppliers"><span><i class="dot ${l}"></i>${levelName(l)}</span><strong>${values[i]}</strong></button>`).join('')}</div></div>`;}
function filteredShipments(){return shipments().filter(sh=>{const s=findSupplier(sh.supplierId);return (state.shipmentFilter==='All'||sh.status===state.shipmentFilter)&&(state.shipmentMode==='all'||sh.mode===state.shipmentMode)&&`${sh.id} ${s.name} ${s.country}`.toLowerCase().includes(state.shipmentQuery.toLowerCase());});}
function shipmentPage(){const data=shipments();return `${pageHead('DELIVERY VISIBILITY','Every shipment. A clearer picture.','Follow delivery windows and surface the shipments that need attention.',`${demoLabel}<button class="btn" data-action="export-shipments">${icon('download')}Export shipments</button>`)}<div class="stats">${stat('box','Demo shipments',data.length,'<b>12 suppliers</b><span>· US distribution hub</span>')}${stat('truck','On track',data.filter(s=>s.status==='On track').length,'<b>Within the planned window</b>')}${stat('warning','At risk',data.filter(s=>s.status==='At risk').length,'<b class="red">Forecast needs review</b>','red')}${stat('clock','Delayed',data.filter(s=>s.status==='Delayed').length,'<b class="red">Past the delivery window</b>','red')}</div><div class="card table-card full-table"><div class="table-toolbar"><div class="tabs" role="group" aria-label="Filter shipments">${['All','On track','At risk','Delayed'].map(f=>`<button class="tab ${state.shipmentFilter===f?'active':''}" data-shipment-filter="${f}" aria-pressed="${state.shipmentFilter===f}">${f}<span class="count">${f==='All'?data.length:data.filter(s=>s.status===f).length}</span></button>`).join('')}</div><div class="filter-set"><div class="input-search">${icon('search')}<input id="shipment-query" aria-label="Search shipments" placeholder="Shipment or supplier..." value="${esc(state.shipmentQuery)}"></div><select id="shipment-mode" aria-label="Transport mode"><option value="all">All transport</option>${['Ocean','Air','Road'].map(m=>`<option ${state.shipmentMode===m?'selected':''}>${m}</option>`).join('')}</select></div></div><div class="table-scroll"><table aria-label="Shipment tracking"><thead><tr><th>Shipment / supplier</th><th>Route & transport</th><th>Planned arrival</th><th>Status</th><th>Est. delay</th><th>Order value</th><th>Details</th></tr></thead><tbody id="shipment-rows">${shipmentRows()}</tbody></table></div><div class="table-foot"><span id="shipment-count">${filteredShipments().length} matching shipments</span><span>Fictional orders · No carrier feed connected</span></div></div>`;}
function shipmentRows(){const rows=filteredShipments();if(!rows.length)return `<tr><td colspan="7"><div class="empty">${icon('truck')}<h3>No matching shipments</h3><p>Try another status, transport mode, or search.</p><button class="btn" data-action="clear-shipments">Reset filters</button></div></td></tr>`;return rows.map(sh=>{const s=findSupplier(sh.supplierId);return `<tr><td><div class="metric-pair"><strong>${sh.id}</strong><small>${esc(s.name)}</small></div></td><td><div class="metric-pair"><strong>${esc(s.country)} ${icon('arrow')} US hub</strong><small>${icon(sh.mode==='Ocean'?'ship':sh.mode==='Air'?'plane':'truck')} ${sh.mode}</small></div></td><td class="mono">${formatDate(sh.due)}</td><td><span class="badge ${sh.status.toLowerCase().replace(' ','-')}">${sh.status}</span></td><td class="mono">${sh.delay?`+${sh.delay} days`:'—'}</td><td class="mono">${money(sh.value,false)}</td><td><button class="icon-button" data-action="shipment" data-id="${sh.id}" aria-label="View shipment ${sh.id}">${icon('chevron')}</button></td></tr>`;}).join('');}
function formatDate(d){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));}
function scenarioPage(){const s=findSupplier(state.scenarioId)||suppliers()[0];return `${pageHead('WHAT IF, BEFORE WHAT NEXT','Make room for a better outcome.','Test a disruption or a mitigation. See how the risk index responds.',demoLabel)}<div class="info-banner">${icon('sliders')}<div><strong>A planning sandbox, powered by transparent assumptions.</strong> Change one input at a time or combine actions. These are illustrative estimates, not predictions from a trained model.</div></div><div class="scenario-grid"><section class="card scenario-inputs"><h2>Build your scenario</h2><p class="card-desc" style="margin-bottom:22px">Start with a supplier, then explore the trade-offs.</p><label class="field-label" for="scenario-supplier">Supplier</label><select class="full-select" id="scenario-supplier">${suppliers().map(x=>`<option value="${esc(x.id)}" ${x.id===s.id?'selected':''}>${esc(x.name)} · ${riskScore(x)}/100</option>`).join('')}</select><div class="preset-row"><button class="preset" data-preset="disruption">Port disruption</button><button class="preset" data-preset="mitigation">Mitigation plan</button><button class="preset" data-preset="reset">Reset inputs</button></div><div class="scenario-divider"></div>${rangeControl('disruption','Additional disruption',0,14,'days','Extra lead time caused by a hypothetical disruption.')}${rangeControl('buffer','Planning buffer',0,14,'days','Offsets effective delay exposure; does not change supplier performance.')}${rangeControl('reliability','On-time delivery improvement',0,25,'pp','Percentage-point improvement in the historical on-time rate.')}${rangeControl('diversification','Reduce supplier dependency',0,60,'pp','Percentage-point reduction in category dependency. Procurement cost is not modeled.')}<button class="text-button" data-action="model">Understand the assumptions ${icon('arrow')}</button></section><section><div class="card scenario-result" id="scenario-result" aria-live="polite">${scenarioResult(s)}</div>${savedScenarios()}</section></div>`;}
function rangeControl(id,label,min,max,unit,help){return `<div class="control-group"><div class="control-label"><label for="range-${id}">${label}</label><output class="range-value" id="value-${id}" for="range-${id}">${state.params[id]} ${unit}</output></div><input type="range" id="range-${id}" data-param="${id}" min="${min}" max="${max}" step="1" value="${state.params[id]}"><div class="range-endpoints"><span>${min} ${unit}</span><span>${max} ${unit}</span></div><p class="control-help">${help}</p></div>`;}
function scenarioResult(s){const before=riskScore(s),after=simulate(s,state.params),delta=after.score-before,baseDelay=estimatedDelay(s),changed=Object.values(state.params).some(v=>v!==0);return `<div class="result-heading"><h2>The potential impact</h2><span class="small-tag">Demo risk index</span></div><div class="flex between"><span class="small muted">${esc(s.name)}</span><span class="small muted">${esc(s.country)}</span></div><div class="compare-grid"><div class="compare-box"><div class="overline">Current</div><div class="large-num ${riskLevel(before)}">${before}</div>${badge(before)}</div><div class="compare-arrow">${icon('arrow')}</div><div class="compare-box projected"><div class="overline">Scenario</div><div class="large-num ${riskLevel(after.score)}">${after.score}</div>${badge(after.score)}</div></div><div class="impact ${delta>0?'worse':''}"><strong>${icon(delta>0?'arrowUp':delta<0?'arrowDown':'sliders')}${delta===0?(changed?'No rounded index change':'Your starting point'):delta<0?`${Math.abs(delta)}-point reduction in risk`:`${delta}-point increase in risk`}</strong><p>${!changed?'Adjust the inputs to see what could change.':delta<0?'The combined assumptions improve this supplier’s risk profile.':delta>0?'The disruption increases exposure. Try adding a buffer or reducing dependency.':'Changes may offset each other or be too small to affect the rounded index.'}</p></div><div class="result-row"><span>Estimated delay exposure</span><strong>${baseDelay} → ${after.delay} days</strong></div><div class="result-row"><span>On-time delivery assumption</span><strong>${s.on_time_rate}% → ${after.on_time_rate}%</strong></div><div class="result-row"><span>Category dependency</span><strong>${s.dependency}% → ${after.dependency}%</strong></div><p class="scenario-disclaimer">The index is a weighted heuristic, not a probability of disruption. Cost, capacity, and correlations are outside this prototype.</p><button class="btn primary full" data-action="save-scenario" ${!changed?'disabled':''}>${icon('plus')}Save scenario to action plan</button>`;}
function savedScenarios(){if(!state.scenarios.length)return '';return `<div class="card saved-scenarios"><div class="card-head"><h2>Saved explorations</h2><span class="small-tag">This browser</span></div>${state.scenarios.slice(-3).reverse().map(s=>`<div class="saved-row"><div><strong>${esc(s.supplierName)}</strong><small>${esc(s.summary)}</small></div><div class="saved-scores">${s.before}${icon('arrow')}<strong>${s.after}</strong></div></div>`).join('')}</div>`;}
function actionPage(){const pending=state.tasks.filter(t=>!t.done),done=state.tasks.filter(t=>t.done);return `${pageHead('FROM INSIGHT TO ACTION','A plan for what comes next.','Turn observations and scenarios into a manageable next step.',`<button class="btn primary" data-action="new-task">${icon('plus')}Add a task</button>`)}<div class="action-grid"><section class="card"><div class="card-head"><h2>Your mitigation plan</h2><span class="small-tag">Saved in this browser</span></div><div class="task-stats"><span><strong>${pending.length}</strong>Open tasks</span><span><strong>${done.length}</strong>Completed</span><span><strong>${state.scenarios.length}</strong>Scenarios saved</span></div>${state.tasks.length?[...pending,...done].map(t=>`<div class="task-item ${t.done?'done':''}"><input type="checkbox" data-task-check="${esc(t.id)}" ${t.done?'checked':''} aria-label="Mark ${esc(t.title)} ${t.done?'incomplete':'complete'}"><div class="task-body"><strong>${esc(t.title)}</strong><p>${esc(t.note)}</p><div class="task-meta"><span>${esc(findSupplier(t.supplierId)?.name||'General task')}</span><span>•</span><span>${esc(t.source||'Manual task')}</span></div></div><button class="icon-button" data-action="delete-task" data-id="${esc(t.id)}" aria-label="Remove task ${esc(t.title)}">${icon('close')}</button></div>`).join(''):`<div class="empty">${icon('checkList')}<h3>A clear space for your next step</h3><p>Add a task or save a scenario to start your plan.</p><button class="btn" data-nav="scenarios">Explore a scenario</button></div>`}</section><aside class="card mini-notes">${icon('leaf')}<h3>Small actions. Stronger supply chains.</h3><p>Start with the suppliers that combine high risk with significant annual spend. A clear next step is often more useful than a perfect forecast.</p><p>Tasks, saved scenarios, watchlists, and imported suppliers stay in this browser. No messages are sent and no supplier systems are updated.</p><button class="text-button" style="margin-top:18px" data-nav="suppliers">Explore your suppliers ${icon('arrow')}</button><div class="scenario-divider"></div><button class="reset-link" data-action="reset-demo">Restore original demo workspace</button></aside></div>`;}

function showOverlay(html,drawer=false){overlayReturnFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay ${drawer?'drawer-overlay':''}" data-overlay><div class="${drawer?'drawer':'modal'}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">${html}</div></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>{$('#overlay-root input:not([type=file]),#overlay-root select,#overlay-root button,#overlay-root [tabindex="-1"]')?.focus();});}
function closeOverlay(restore=true){if(!$('#overlay-root').children.length)return;$('#overlay-root').innerHTML='';document.body.style.overflow='';activeSupplier=null;if(restore&&overlayReturnFocus?.isConnected)overlayReturnFocus.focus();}
function modalHeader(title){return `<div class="modal-header"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;}
function openSupplier(id){const s=findSupplier(id);if(!s)return;const score=riskScore(s),factors=riskFactors(s),watch=state.watchlist.includes(id);activeSupplier=id;showOverlay(`<div class="drawer-header"><span>SUPPLIER INTELLIGENCE / ${esc(s.id)}</span><button class="icon-button" data-action="close" aria-label="Close supplier details">${icon('close')}</button></div><div class="drawer-body"><div class="supplier-profile"><span class="supplier-logo ${riskLevel(score)}">${esc(s.initials)}</span><div><h2 id="dialog-title">${esc(s.name)}</h2><p>${esc(s.city)}, ${esc(s.country)} · ${esc(s.category)}</p></div></div><div class="drawer-score"><div><p>DEMO RISK INDEX / 100</p><div class="large-num ${riskLevel(score)}">${score}</div><p>Higher means more risk</p></div>${badge(score)}</div><div class="section-header"><h3>What is driving the index?</h3><span class="small-tag">Weighted contribution</span></div>${factors.map(f=>`<div class="factor"><div class="factor-head"><span>${f.name}</span><strong>${f.contribution.toFixed(1)} / ${(f.weight*100).toFixed(0)} pts</strong></div><div class="factor-bar"><i style="width:${f.value}%"></i></div><small>${esc(f.detail)} · ${(f.weight*100).toFixed(0)}% weight</small></div>`).join('')}<div class="drawer-facts"><div><label>Annual spend</label><strong>${money(s.spend,false)}</strong></div><div><label>Estimated delay exposure</label><strong>${estimatedDelay(s)} days</strong></div><div><label>On-time delivery rate</label><strong>${s.on_time_rate}%</strong></div><div><label>Defect rate</label><strong>${s.defect_rate}%</strong></div></div><div class="drawer-actions"><button class="btn primary" data-action="simulate" data-id="${esc(id)}">${icon('sliders')}Test a scenario</button><button class="btn" data-action="watch" data-id="${esc(id)}">${icon('star')}${watch?'On your watchlist':'Add to watchlist'}</button></div><button class="text-button" style="margin-top:21px" data-action="new-task" data-id="${esc(id)}">${icon('plus')}Create a mitigation task</button><p class="drawer-note">${s.imported?'Imported supplier data':'Fictional supplier data'} · This prototype uses an explainable heuristic. The score is an index, not a disruption probability. No trained model is connected.</p></div>`,true);activeSupplier=id;}
function openShipment(id){const sh=shipments().find(x=>x.id===id);if(!sh)return;const s=findSupplier(sh.supplierId);const forecast=new Date(sh.due+'T12:00:00Z');forecast.setUTCDate(forecast.getUTCDate()+Math.ceil(sh.delay));showOverlay(`${modalHeader(`Shipment ${sh.id}`)}<div class="modal-body"><div class="flex between" style="margin-bottom:23px"><span class="badge ${sh.status.toLowerCase().replace(' ','-')}">${sh.status}</span><span class="small muted">Demo shipment</span></div><h3 style="margin-top:0">${esc(s.name)} → Indianapolis hub</h3><p>${esc(s.city)}, ${esc(s.country)} · ${sh.mode} freight</p><div class="drawer-facts"><div><label>Planned arrival</label><strong>${formatDate(sh.due)}, 2026</strong></div><div><label>Estimated arrival</label><strong>${formatDate(forecast.toISOString().slice(0,10))}, 2026</strong></div><div><label>Estimated delay</label><strong>${sh.delay} days</strong></div><div><label>Shipment value</label><strong>${money(sh.value,false)}</strong></div></div><div class="info-banner neutral">${icon('info')}<div>Dates and status are demonstration records. The delay estimate comes from supplier-level assumptions; no carrier tracking is connected.</div></div></div><div class="modal-foot"><button class="btn primary" data-action="supplier" data-id="${esc(s.id)}">Inspect supplier ${icon('arrow')}</button></div>`);}
function openModel(){showOverlay(`${modalHeader('The thinking behind the index')}<div class="modal-body"><div class="info-banner">${icon('info')}<div><strong>Interactive prototype · No trained model connected.</strong> All initial suppliers, shipments, and signals are fictional. Imported values use the same transparent calculations.</div></div><p>This prototype demonstrates the workflow for the Supply Chain Risk Prediction System: organize supplier data, identify risk drivers, estimate delay exposure, and explore mitigation options.</p><h3>Risk index: 0–100</h3><p>Normalize five inputs, then take a weighted sum. Higher values indicate greater relative exposure. Scores of 65+ are high risk; 35–64 are medium; 0–34 are low. These bands are prototype assumptions.</p><table class="notes-table"><thead><tr><th>Input</th><th>Normalization, capped at 100</th><th>Weight</th></tr></thead><tbody><tr><td>Delivery reliability</td><td>(100 − on-time %) × 1.45</td><td>40%</td></tr><tr><td>Historical delays</td><td>Average delay days × 8.5</td><td>25%</td></tr><tr><td>Quality issues</td><td>Defect % × 18</td><td>15%</td></tr><tr><td>Supplier dependency</td><td>Share of category purchasing, %</td><td>12%</td></tr><tr><td>Lead-time volatility</td><td>Illustrative variability index, 0–100</td><td>8%</td></tr></tbody></table><h3>Delay exposure estimate</h3><div class="formula">0.8 × average delay days<br>+ 0.045 × (100 − on-time %)<br>+ 0.018 × volatility<br>+ 0.15 × defect %</div><p style="margin-top:13px">This heuristic is in days and is not an empirically calibrated forecast. In the scenario lab, buffer days offset effective historical delay exposure; disruption days also add 3 volatility points per day. Dependency and on-time rate stay between 0 and 100.</p><h3>Path to the predictive system</h3><p>The project’s intended modeling stack includes Python, Pandas, SQL, scikit-learn, XGBoost, and Power BI. A production version would connect a trained model and evaluate supplier-risk classification and delay regression using time-based holdouts and features available at prediction time.</p><p>No model performance is measured by this prototype. Country and region are used for visualization and filtering, not as scoring factors.</p><h3>Where your changes live</h3><p>Watchlists, imports, tasks, and scenarios are saved in this browser’s local storage. CSV import adds supplier records; it does not create shipment history or map coordinates. The supplier-level historical delivery rate is spend-weighted in the overview. Annual spend at risk is the sum of annual spend for suppliers with index ≥65.</p></div><div class="modal-foot"><button class="btn primary" data-action="close">Got it ${icon('check')}</button></div>`);}
function openSearch(){showOverlay(`<div class="input-search">${icon('search')}<input id="global-query" placeholder="Search a supplier, country, or shipment..." aria-label="Search all records"><button class="icon-button" data-action="close" aria-label="Close search">${icon('close')}</button></div><h2 id="dialog-title" class="hidden">Search your network</h2><div class="search-results" id="global-results">${searchResults('')}</div><div class="search-shortcut"><span>Search your demo network</span><span>Esc to close</span></div>`);$('.modal').classList.add('search-modal');requestAnimationFrame(()=>$('#global-query')?.focus());}
function searchResults(q){const term=q.trim().toLowerCase(),ss=suppliers().filter(s=>`${s.name} ${s.country} ${s.id} ${s.category}`.toLowerCase().includes(term)).slice(0,6),ships=term?shipments().filter(s=>s.id.toLowerCase().includes(term)).slice(0,4):[];if(!ss.length&&!ships.length)return `<div class="empty">${icon('search')}<h3>No matches yet</h3><p>Try a supplier name, country, or shipment ID.</p></div>`;return `${ss.map(s=>`<button class="search-result" data-action="supplier" data-id="${esc(s.id)}"><span class="supplier-logo">${esc(s.initials)}</span><span class="result-copy"><strong>${esc(s.name)}</strong><small>${esc(s.country)} · ${esc(s.category)}</small></span>${badge(riskScore(s))}</button>`).join('')}${ships.map(s=>`<button class="search-result" data-action="shipment" data-id="${s.id}"><span class="supplier-logo">${icon('truck')}</span><span class="result-copy"><strong>${s.id}</strong><small>${esc(findSupplier(s.supplierId).name)} · ${s.status}</small></span>${icon('chevron')}</button>`).join('')}`;}
function openImport(){showOverlay(`${modalHeader('Bring your suppliers into view')}<div class="modal-body"><p>Import up to 500 suppliers as a CSV. New records are added to this browser’s directory. Existing IDs cannot be overwritten.</p><button class="text-button" data-action="template">${icon('download')}Download a sample CSV</button><div class="import-drop">${icon('upload')}<label class="field-label" for="csv-file">Choose your supplier CSV</label><span class="small muted">Numeric percentages use 0–100, without the % symbol.</span><input type="file" id="csv-file" accept=".csv,text/csv"></div><div id="import-feedback" role="status"></div><h3>Required columns</h3><div class="column-list">${CSV_FIELDS.map(f=>`<code>${f}</code>`).join('')}</div><p>Regions: Americas, Europe, Asia Pacific, or Middle East &amp; Africa. Spend is annual USD. Defect rate, on-time rate, and dependency are percentages; volatility is a 0–100 index.</p></div><div class="modal-foot"><button class="btn" data-action="close">Cancel</button><button class="btn primary" id="import-submit" data-action="import-submit" disabled>${icon('plus')}Import suppliers</button></div>`);}
let pendingImport=null;
function openTask(supplierId=''){showOverlay(`${modalHeader('A clear next step')}<form id="task-form"><div class="modal-body"><label class="field-label" for="task-title">Task</label><input class="text-field" id="task-title" name="title" required maxlength="160" placeholder="e.g. Review an alternate supplier"><label class="field-label" for="task-supplier">Related supplier</label><select class="full-select" id="task-supplier" name="supplierId"><option value="">General task</option>${suppliers().map(s=>`<option value="${esc(s.id)}" ${s.id===supplierId?'selected':''}>${esc(s.name)}</option>`).join('')}</select><label class="field-label" for="task-note" style="margin-top:20px">Notes <span class="muted">(optional)</span></label><textarea class="textarea" name="note" id="task-note" maxlength="1200" placeholder="What needs to happen, and why?"></textarea><p style="margin-top:13px">Saved to your local action plan. No message or request is sent.</p></div><div class="modal-foot"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">${icon('plus')}Add to plan</button></div></form>`);requestAnimationFrame(()=>$('#task-title')?.focus());}
function scenarioSummary(p){return [p.disruption?`+${p.disruption} disruption days`:null,p.buffer?`${p.buffer}-day buffer`:null,p.reliability?`+${p.reliability} pp on-time`:null,p.diversification?`−${p.diversification} pp dependency`:null].filter(Boolean).join(' · ');}
function saveScenario(){const s=findSupplier(state.scenarioId),after=simulate(s,state.params),before=riskScore(s),summary=scenarioSummary(state.params);if(!Object.values(state.params).some(v=>v!==0))return;const previous=state.scenarios.at(-1);if(previous&&previous.supplierId===s.id&&previous.summary===summary){toast('This scenario is already saved. Explore it in your action plan.');return;}const id=`scenario-${Date.now()}`;state.scenarios.push({id,supplierId:s.id,supplierName:s.name,before,after:after.score,summary,params:{...state.params}});state.tasks.push({id:`task-${Date.now()}`,supplierId:s.id,title:`Review scenario for ${s.name}`,note:`${summary}. Demo risk index: ${before} → ${after.score}; delay exposure: ${estimatedDelay(s)} → ${after.delay} days. Validate costs and feasibility before taking action.`,done:false,source:'Saved scenario'});persist();render();toast('Scenario saved. A review task is ready in your action plan.');}
function exportSuppliers(){const data=filteredSuppliers().map(s=>({...s,risk_index:riskScore(s),risk_level:riskLevel(riskScore(s)),estimated_delay_days:estimatedDelay(s),data_source:s.imported?'Imported':'Fictional demo',snapshot:SNAPSHOT}));download(toCSV(data,[...CSV_FIELDS,'risk_index','risk_level','estimated_delay_days','data_source','snapshot']),`supplychainrisk-suppliers-${SNAPSHOT}.csv`);toast(`Exported ${data.length} matching suppliers as CSV.`);}

document.addEventListener('click',async e=>{
  const navEl=e.target.closest('[data-nav]');if(navEl){e.preventDefault();nav(navEl.dataset.nav);return;}
  const filter=e.target.closest('[data-risk]');if(filter){state.risk=filter.dataset.risk;render();return;}
  const shipFilter=e.target.closest('[data-shipment-filter]');if(shipFilter){state.shipmentFilter=shipFilter.dataset.shipmentFilter;render();return;}
  const sort=e.target.closest('[data-sort]');if(sort){if(state.sort===sort.dataset.sort)state.sortDir*=-1;else{state.sort=sort.dataset.sort;state.sortDir=state.sort==='name'?1:-1;}updateSupplierTable();return;}
  const preset=e.target.closest('[data-preset]');if(preset){state.params=preset.dataset.preset==='disruption'?{reliability:0,disruption:7,buffer:0,diversification:0}:preset.dataset.preset==='mitigation'?{reliability:10,disruption:0,buffer:5,diversification:25}:{reliability:0,disruption:0,buffer:0,diversification:0};render();return;}
  const target=e.target.closest('[data-action]');if(!target){if(e.target.matches('[data-overlay]'))closeOverlay();return;}
  const id=target.dataset.id,action=target.dataset.action;
  if(action==='close')closeOverlay();
  else if(action==='model')openModel();
  else if(action==='supplier')openSupplier(id);
  else if(action==='shipment')openShipment(id);
  else if(action==='search')openSearch();
  else if(action==='menu'){$('.sidebar').classList.add('open');$('.mobile-scrim').classList.add('visible');}
  else if(action==='menu-close'){$('.sidebar').classList.remove('open');$('.mobile-scrim').classList.remove('visible');}
  else if(action==='signals'){nav('overview');document.querySelector('.signals')?.scrollIntoView({behavior:'smooth',block:'center'});}
  else if(action==='review-high'){state.risk='high';state.region='all';state.query='';nav('suppliers');}
  else if(action==='clear-filters'){state.risk='all';state.region='all';state.query='';state.sort='score';state.sortDir=-1;render();}
  else if(action==='clear-shipments'){state.shipmentQuery='';state.shipmentFilter='All';state.shipmentMode='all';render();}
  else if(action==='watch'){const was=state.watchlist.includes(id);state.watchlist=was?state.watchlist.filter(x=>x!==id):[...state.watchlist,id];persist();const opened=activeSupplier;render();if(opened)openSupplier(opened);toast(`${was?'Removed from':'Added to'} your watchlist.`);}
  else if(action==='simulate'){state.scenarioId=id;state.params={reliability:0,disruption:0,buffer:0,diversification:0};nav('scenarios');}
  else if(action==='save-scenario')saveScenario();
  else if(action==='new-task')openTask(id||'');
  else if(action==='delete-task'){const t=state.tasks.find(t=>t.id===id);state.tasks=state.tasks.filter(t=>t.id!==id);persist();render();toast('Task removed.');lastRemoved=t;showUndoToast();}
  else if(action==='undo-task'){if(lastRemoved){state.tasks.push(lastRemoved);lastRemoved=null;persist();render();toast('Task restored.');}}
  else if(action==='export')exportSuppliers();
  else if(action==='export-shipments'){const data=filteredShipments().map(s=>({...s,supplier:findSupplier(s.supplierId).name,data_source:'Fictional demo'}));download(toCSV(data,['id','supplier','supplierId','destination','mode','value','due','status','delay','score','data_source']),`supplychainrisk-shipments-${SNAPSHOT}.csv`);toast(`Exported ${data.length} matching shipments.`);}
  else if(action==='import'){pendingImport=null;openImport();}
  else if(action==='template'){const sample={id:'CUSTOM-001',name:'Example Supplier',country:'United States',region:'Americas',category:'Electronics',spend:1000000,on_time_rate:92,avg_delay_days:2,defect_rate:1,dependency:30,volatility:25};download(toCSV([sample],CSV_FIELDS),'supplychainrisk-import-template.csv');}
  else if(action==='import-submit'&&pendingImport){state.imported.push(...pendingImport);const count=pendingImport.length;pendingImport=null;persist();state.risk='all';state.region='all';state.query='';closeOverlay(false);nav('suppliers');toast(`Imported ${count} supplier${count===1?'':'s'}. Risk indices are ready.`);}
  else if(action==='reset-demo')showOverlay(`${modalHeader('Restore your demo workspace?')}<div class="modal-body"><p>This replaces this prototype’s local watchlist, tasks, saved scenarios, and imported records with the original demo. Export any supplier data you want to keep first.</p></div><div class="modal-foot"><button class="btn" data-action="close">Keep my changes</button><button class="btn danger" data-action="confirm-reset">Restore demo</button></div>`);
  else if(action==='confirm-reset'){state.imported=[];state.watchlist=['SUP-001','SUP-004'];state.tasks=defaultTasks.map(t=>({...t}));state.scenarios=[];state.risk='all';state.region='all';state.query='';state.scenarioId='SUP-001';state.params={reliability:0,disruption:0,buffer:0,diversification:0};persist();closeOverlay(false);render();toast('Original demo workspace restored.');}
});
let lastRemoved=null;
function showUndoToast(){$('#toast').innerHTML=`Task removed. <button data-action="undo-task" style="text-decoration:underline;color:#e5efce;margin-left:12px;pointer-events:auto">Undo</button>`;}
document.addEventListener('input',e=>{const t=e.target;if(t.id==='supplier-query'){state.query=t.value;updateSupplierTable();}else if(t.id==='shipment-query'){state.shipmentQuery=t.value;$('#shipment-rows').innerHTML=shipmentRows();$('#shipment-count').textContent=`${filteredShipments().length} matching shipments`;}else if(t.id==='global-query'){$('#global-results').innerHTML=searchResults(t.value);}else if(t.dataset.param){state.params[t.dataset.param]=Number(t.value);const unit=['reliability','diversification'].includes(t.dataset.param)?'pp':'days';$(`#value-${t.dataset.param}`).textContent=`${t.value} ${unit}`;$('#scenario-result').innerHTML=scenarioResult(findSupplier(state.scenarioId));}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='region-select'){state.region=t.value;render();}else if(t.id==='risk-select'){state.risk=t.value;render();}else if(t.id==='shipment-mode'){state.shipmentMode=t.value;render();}else if(t.id==='scenario-supplier'){state.scenarioId=t.value;state.params={reliability:0,disruption:0,buffer:0,diversification:0};render();}else if(t.dataset.taskCheck){const task=state.tasks.find(x=>x.id===t.dataset.taskCheck);if(task){task.done=t.checked;persist();render();toast(task.done?'Task marked complete.':'Task reopened.');}}else if(t.id==='csv-file'){
  const file=t.files?.[0];pendingImport=null;$('#import-submit').disabled=true;if(!file)return;
  try{if(file.size>2*1024*1024)throw new Error('Please use a CSV smaller than 2 MB.');pendingImport=importSuppliers(await file.text(),suppliers().map(s=>s.id));$('#import-feedback').innerHTML=`<div class="info-banner">${icon('check')}<div><strong>${pendingImport.length} supplier${pendingImport.length===1?'':'s'} ready to import.</strong> Validation passed. Select Import suppliers to add them to your directory.</div></div>`;$('#import-submit').disabled=false;}catch(error){$('#import-feedback').innerHTML=`<div class="import-error">${esc(error.message)}</div>`;}
}});
document.addEventListener('submit',e=>{if(e.target.id==='task-form'){e.preventDefault();const form=new FormData(e.target),title=form.get('title').trim();if(!title){$('#task-title').setCustomValidity('Enter a task title.');$('#task-title').reportValidity();return;}state.tasks.push({id:`task-${Date.now()}`,supplierId:form.get('supplierId'),title,note:form.get('note').trim(),done:false,source:'Manual task'});persist();closeOverlay(false);nav('actions');toast('Task added to your local action plan.');}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'){closeOverlay();$('.sidebar')?.classList.remove('open');$('.mobile-scrim')?.classList.remove('visible');}if(e.key==='Enter'&&e.target.matches('.map-pin')){openSupplier(e.target.dataset.id);}if(e.key==='Tab'&&$('#overlay-root').children.length){const focusable=[...$('#overlay-root').querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(pages[page]&&state.page!==page){state.page=page;closeOverlay(false);render();}});
render();
